/* Fontes embutidas (subset latin, SIL Open Font License 1.1 — ver assets/OFL.txt).
   Gerado a partir de @fontsource/barlow e @fontsource/barlow-semi-condensed. */
const FACES = [
  ["Barlow", 400, "normal", ""],
  ["Barlow", 500, "normal", ""],
  ["Barlow", 600, "normal", ""],
  ["Barlow", 700, "normal", ""],
  ["Barlow Semi Condensed", 600, "normal", ""],
  ["Barlow Semi Condensed", 700, "italic", ""],
  ["Barlow Semi Condensed", 800, "italic", ""],
];

export async function loadFonts() {
  if (!("FontFace" in window)) return;
  await Promise.all(FACES.map(async ([family, weight, style, b64]) => {
    const bin = Uint8Array.from(atob(b64), c => c.charCodeAt(0));
    const face = new FontFace(family, bin, { weight: String(weight), style });
    await face.load();
    document.fonts.add(face);
  }));
}
